#!/usr/bin/env python3
"""Embed the offline UI in flash; reuse a matching compressed stream."""
import gzip
import re
import zlib
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
# Git for Windows may have checked out CRLF; encode the same HTML on every OS.
source = (ROOT / 'web/index.html').read_text(encoding='utf-8').encode('utf-8')
target = ROOT / 'firmware/esp8266/WebUi.h'
# Different zlib/Python versions can encode identical HTML differently. Keep a
# valid checked-in stream to avoid dirty generated files after a Windows build.
if target.exists():
    match = re.search(r'UPS_WEB_GZIP\[\] PROGMEM = \{(.*?)\};', target.read_text(encoding='utf-8'), re.S)
    if match:
        try:
            existing = bytes(int(value, 16) for value in re.findall(r'0x([0-9a-fA-F]{2})', match.group(1)))
            if gzip.decompress(existing) == source:
                print(f'UI already embedded: {len(source)} bytes as {len(existing)} gzip bytes')
                raise SystemExit(0)
        except (OSError, EOFError, ValueError, zlib.error):
            pass  # Rebuild a stale or damaged generated header below.
payload = gzip.compress(source, compresslevel=9, mtime=0)
lines = [
    '// Generated by tools/embed_web.py; edit web/index.html instead.',
    '#pragma once',
    '#include <Arduino.h>',
    'static const uint8_t UPS_WEB_GZIP[] PROGMEM = {'
]
for offset in range(0, len(payload), 16):
    lines.append('  ' + ','.join(f'0x{b:02x}' for b in payload[offset:offset+16]) + ',')
lines += ['};', 'static const size_t UPS_WEB_GZIP_SIZE = sizeof(UPS_WEB_GZIP);', '']
target.write_text('\n'.join(lines), encoding='utf-8', newline='\n')
print(f'Embedded {len(source)} bytes as {len(payload)} gzip bytes')
